nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
  .e2 { stroke: --teal-deep; }
}
|group#visual| "V8 · A complete reservation intent" { layout: flow; direction: column; gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "Incomplete property" { width: 240; } [
    |cell#detail| "post.stock = pre.stock − quantity is\ninsufficient by itself. This is a\nhandler example, not the approve\nrecipe."
  ]
  |box#n2| "Counterexample · quantity\nzero" { width: 240; } [
    |cell#detail| "Stock can remain unchanged and the\nequation still holds. A promised\nreservation might also be absent."
  ]
  |box#n3| "Corrected obligations" { width: 240; } [
    |cell#detail| "Require positive quantity, exact stock\nrelation, nonnegative stock,\nreservation existence and the correct\nentity identities."
  ]
  |box#n4| "Scope of the evidence" { width: 240; } [
    |cell#detail| "Model bounds and assumptions are\nexplicit. Actual native refinement and\nimplementation mutants are separate\nwitnesses; none proves every\ndeployment."
  ]
  n1 -> n2 "Passes the equation" .e1 { along: 0.35; }
  n2 -> n3 "Correct the obligations" .e2 { along: 0.5; }
]
